//! R036/19: Four-pane workstation geometry with focus ownership.
use super::Error;
use crate::batch7_ramfs::{RamFs,CONTENT_MAX,PATH_MAX};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct Rect{pub x:u16,pub y:u16,pub w:u16,pub h:u16}pub struct Layout{owner:u64,panes:[Rect;4],active:u8}impl Layout{pub fn new(owner:u64,width:u16,height:u16)->Result<Self,Error>{if owner==0||width<800||height<480{return Err(Error::Invalid);}let left=width/5;let right=width/4;let center=width-left-right;let upper=height*3/4;Ok(Self{owner,panes:[Rect{x:0,y:0,w:left,h:height},Rect{x:left,y:0,w:center,h:upper},Rect{x:left,y:upper,w:center,h:height-upper},Rect{x:left+center,y:0,w:right,h:height}],active:1})}pub fn focus(&mut self,owner:u64,slot:u8)->Result<(),Error>{if owner!=self.owner||owner==0{return Err(Error::Denied);}if slot>=4{return Err(Error::Invalid);}self.active=slot;Ok(())}pub fn active(&self)->u8{self.active}pub fn coverage(&self)->u32{self.panes.iter().map(|r|r.w as u32*r.h as u32).sum()}}
#[cfg(test)]mod tests{use super::*;#[test]fn real_functional_regression(){let mut l=Layout::new(7,1200,800).unwrap();assert_eq!(l.coverage(),960000);l.focus(7,2).unwrap();assert_eq!(l.active(),2);assert_eq!(l.focus(8,3),Err(Error::Denied));}}
